548	// ---------- apply_deposit_to_session (S16) ----------
549	
550	/**
551	 * SAGA STEP 1: Atomically reserve a deposit pool drawdown for an upcoming PaymentIntent.
552	 *
553	 * Behavior:
554	 *   1. SELECT FOR UPDATE on `projects.deposit_pool_cents_available`.
555	 *   2. Verify available >= draw_cents. RAISE EXCEPTION if not.
556	 *   3. Decrement available, increment applied.
557	 *   4. INSERT into `project_deposit_transactions` with status='pending_apply'.
558	 *   5. Return the transaction id.
559	 *
560	 * Caller flow: call this BEFORE stripe.paymentIntents.create(). Pass the returned
561	 * transaction_id in the PaymentIntent metadata. The webhook handler then calls:
562	 *   - confirm_deposit_application(txn_id) on payment_intent.succeeded
563	 *   - rollback_deposit_application(txn_id) on payment_intent.payment_failed | canceled
564	 *
565	 * If the caller fails to create the PaymentIntent, they MUST call rollback explicitly.
566	 * A reaper cron should sweep `pending_apply` rows older than 30 minutes and roll them back.
567	 */
568	export interface ApplyDepositToSessionArgs {
569	  projectId: string;
570	  sessionId: string;
571	  drawCents: CentsAmount;
572	  idempotencyKey: InkosIdempotencyKey;          // dedupe on PaymentIntent retries
573	}
574	export type ApplyDepositToSessionResult = {
575	  transaction_id: string;
576	  pool_in_cents: CentsAmount;
577	  pool_applied_cents: CentsAmount;
578	  pool_available_cents: CentsAmount;
579	};
580	
581	// ---------- confirm_deposit_application (S16) ----------
582	
583	/**
584	 * SAGA STEP 2 (success path): Mark a pending_apply transaction as applied.
585	 * Called from the webhook handler on payment_intent.succeeded.
586	 *
587	 * Idempotent — re-running on an already-confirmed txn is a no-op.
588	 * RAISE EXCEPTION if txn was already rolled_back or released.
589	 */
590	export interface ConfirmDepositApplicationArgs {
591	  transactionId: string;
592	  paymentIntentId: string;                      // for cross-reference
593	}
594	export type ConfirmDepositApplicationResult = {
595	  transaction_id: string;
596	  status: 'applied' | 'already_applied';
597	};
598	
599	// ---------- rollback_deposit_application (S16) ----------
600	
601	/**
602	 * SAGA STEP 2 (failure path): Roll back a pending_apply transaction.
603	 * Called from the webhook handler on payment_intent.payment_failed | canceled,
604	 * OR by the reaper cron after 30-min timeout.
605	 *
606	 * Behavior:
607	 *   1. SELECT FOR UPDATE on the txn + parent project.
608	 *   2. Re-increment available, decrement applied.
609	 *   3. Mark txn status='rolled_back', set rolled_back_at + reason.
610	 *
611	 * Idempotent — re-running on an already-rolled-back txn is a no-op.
612	 * RAISE EXCEPTION if txn is already 'applied' (cannot rollback a confirmed txn —
613	 * issue a refund instead via release_deposit_from_session).
614	 */
615	export interface RollbackDepositApplicationArgs {
616	  transactionId: string;
617	  reason: 'payment_failed' | 'payment_canceled' | 'reaper_timeout' | 'manual';
618	}
619	export type RollbackDepositApplicationResult = {
620	  transaction_id: string;
621	  status: 'rolled_back' | 'already_rolled_back';
622	  pool_available_cents: CentsAmount;
623	};
624	
625	// ---------- release_deposit_from_session (S16) ----------
626	
627	/**
628	 * Refund path: re-credit a previously-applied deposit drawdown back to the pool.
629	 *
630	 * Called from refund flow when the original session charge consumed pool funds.
631	 * Partial refunds are supported (release_cents <= original draw_cents).
632	 *
633	 * Behavior:
634	 *   1. SELECT FOR UPDATE on the txn + parent project.
635	 *   2. Verify txn status='applied' (cannot release pending/rolled_back).
636	 *   3. Verify release_cents <= (txn.draw_cents - already-released amount).
637	 *   4. Re-increment available, decrement applied (by release_cents).
638	 *   5. INSERT a child txn with kind='released', parent_transaction_id=txn_id.
639	 *
640	 * NOT idempotent on its own — caller passes a unique idempotency_key in args
641	 * to dedupe on Stripe webhook replay (charge.refunded fires multiple times).
642	 */
643	export interface ReleaseDepositFromSessionArgs {
644	  transactionId: string;                        // original applied txn
645	  releaseCents: CentsAmount;
646	  idempotencyKey: InkosIdempotencyKey;
647	  refundId: string;                             // Stripe refund_xxx for cross-reference
648	}
649	export type ReleaseDepositFromSessionResult = {
650	  release_transaction_id: string;
651	  pool_available_cents: CentsAmount;
652	  total_released_cents: CentsAmount;            // running total released against parent txn
653	};
654	
655	// ---------- studio_l2_payments_enabled (S15) ----------
656	
657	/**
658	 * Capability gate: returns true only if the studio has an active Stripe Connect
659	 * account with `charges_enabled` capability. Used by S16+ in-studio charge code
660	 * paths to refuse charges before the studio's KYC is complete.
661	 *
662	 * Called from: feature-gate layer + UI banner suppression on /dashboard.
663	 *
664	 * `reason` is populated only when `enabled=false`. Possible values:
665	 *   - 'no_connected_account'      — studio has not started Connect onboarding
666	 *   - 'onboarding_pending'        — account exists but KYC incomplete
667	 *   - 'onboarding_restricted'     — Stripe restricted the account (KYC docs needed)
668	 *   - 'onboarding_rejected'       — Stripe permanently rejected
669	 *   - 'charges_disabled'          — Stripe revoked charges capability
670	 */
671	export interface StudioL2PaymentsEnabledArgs {
672	  studioId: string;
673	}
674	export type StudioL2PaymentsEnabledResult = {
675	  enabled: boolean;
676	  reason: string | null;
677	  account_id: string | null;
678	  onboarding_status: ConnectedAccountOnboardingStatus | null;
679	};
680	
681	// ---------- artist_l2_payouts_enabled (S15) ----------
682	
683	/**
684	 * Capability gate for artists who opt into direct payouts.
685	 * Returns true only if the artist has their own active Stripe Connect account
686	 * with `payouts_enabled` AND `transfers` capabilities.
687	 *
688	 * If false, commission splits flow to the studio's connected account and the
689	 * studio pays the artist via existing payroll path (1099 or W-2).
690	 *
691	 * `reason` possible values:
692	 *   - 'self_payouts_disabled'     — artist hasn't opted in (`payouts_self_enabled=false`)
693	 *   - 'no_connected_account'      — opted in but no Stripe account created yet
694	 *   - 'onboarding_pending'        — account exists, KYC incomplete
695	 *   - 'onboarding_restricted'     — Stripe restricted
696	 *   - 'onboarding_rejected'       — permanently rejected
697	 *   - 'transfers_disabled'        — capability missing
698	 *   - 'payouts_disabled'          — capability missing
699	 */
700	export interface ArtistL2PayoutsEnabledArgs {
701	  artistId: string;
702	}
703	export type ArtistL2PayoutsEnabledResult = {
704	  enabled: boolean;
705	  reason: string | null;
706	  account_id: string | null;
707	  onboarding_status: ConnectedAccountOnboardingStatus | null;
708	};
709	
710	// =====================================================================
711	// PRESET SPLIT PERCENTAGES (locked defaults — overridable per studio)
712	// =====================================================================
713	
714	export const DEFAULT_COMMISSION_PCT = {
715	  RESIDENT_ESTABLISHED: 70,    // 70/30 in artist's favor
716	  RESIDENT_NEW: 60,            // 60/40
717	  RESIDENT_FULL_SUPPORT: 50,   // 50/50 when shop covers everything
718	  GUEST: 80,                   // 80/20 in guest's favor
719	  APPRENTICE: 50,              // 50/50 ramp
720	  BOOTH_RENTER: 100,           // booth renter keeps everything (rent invoiced separately)
721	} as const;
722	
723	// =====================================================================
724	// INVARIANTS — Sage scans verify these hold across the codebase
725	// =====================================================================
726	
727	/**
728	 * INVARIANT 1: All money is CentsAmount. Never `number` for money.
729	 * INVARIANT 2: Every Stripe call carries `metadata.inkos_idempotency_key`.
730	 * INVARIANT 3: Every webhook handler's first write is webhook_event_insert.
731	 * INVARIANT 4: `application_fee_amount` is set on every PaymentIntent (never undefined).
732	 * INVARIANT 5: Refunds always pass `reverse_transfer: true` AND `refund_application_fee: true`.
733	 * INVARIANT 6: `subscriptions` and `stripe_charges` are webhook-only writes from app code.
734	 * INVARIANT 7: Dodo (L1) and Stripe (L2) abstractions never share a module.
735	 * INVARIANT 8: Banker's rounding when computing splits to avoid systematic bias.
736	 */
737

