// ---------------------------------------------------------------------------
// Tests 1–5, 7: Track A contract tests (now active — tax mirror landed in process-stripe-event.ts)
// ---------------------------------------------------------------------------

// Test 1: p_tax_amount_cents is forwarded in the S17 tax-pass RPC call
it('[Track A] PI succeeded with tax.amount=250 → STRIPE_CHARGE_UPDATE_STATUS called with p_tax_amount_cents=250', async () => {
  const rpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []
  const sb = makeSupabaseMock(async (fn, args) => {
    rpcCalls.push({ fn, args })
    return { data: { id: 'mock-result' }, error: null }
  })

  const event = makePaymentIntentSucceededEvent({ taxAmount: 250, taxBreakdown: [] })
  await processStripeEvent(event, sb)

  // The S17 tax-pass call is the second invocation of STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK
  const taxPassCall = rpcCalls
    .filter(c => c.fn === RPC.STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK)
    .find(c => 'p_tax_amount_cents' in c.args)
  expect(taxPassCall).toBeDefined()
  expect(taxPassCall?.args.p_tax_amount_cents).toBe(250)
})

// Test 2: Empty tax_breakdown + non-zero tax → single-line UNKNOWN fallback accrual; no tax-line records
it('[Track A] PI succeeded with empty tax_breakdown → no COMMISSION_SPLIT_TAX_LINE_RECORD; TAX_REMITTANCE_ACCRUE with jurisdiction=UNKNOWN', async () => {
  const rpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []
  const sb = makeSupabaseMock(async (fn, args) => {
    rpcCalls.push({ fn, args })
    return { data: { id: 'mock-result' }, error: null }
  })

  const event = makePaymentIntentSucceededEvent({ taxAmount: 300, taxBreakdown: [] })
  await processStripeEvent(event, sb)

  const taxLineRecords = rpcCalls.filter(c => c.fn === RPC.COMMISSION_SPLIT_TAX_LINE_RECORD)
  expect(taxLineRecords).toHaveLength(0)

  const accruals = rpcCalls.filter(c => c.fn === RPC.TAX_REMITTANCE_ACCRUE)
  expect(accruals.length).toBeGreaterThanOrEqual(1)
  const unknownAccrual = accruals.find(c => c.args.p_jurisdiction === 'UNKNOWN')
  expect(unknownAccrual).toBeDefined()
})

// Test 3: 2-entry tax_breakdown → COMMISSION_SPLIT_TAX_LINE_RECORD called twice with correct jurisdictions
it('[Track A] PI succeeded with 2 tax_breakdown entries → COMMISSION_SPLIT_TAX_LINE_RECORD called twice with correct jurisdictions', async () => {
  const rpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []

  // Build a mock where commission_splits maybeSingle() returns a split row
  const fromFn = vi.fn((table: string) => ({
    select: vi.fn(() => ({
      eq: vi.fn(() => ({
        maybeSingle: vi.fn(async () => {
          if (table === 'stripe_charges') return { data: { studio_id: 'studio-test-001' }, error: null }
          if (table === 'commission_splits') return { data: { id: 'split-test-001' }, error: null }
          if (table === 'locations') return { data: { id: 'loc-test-001' }, error: null }
          return { data: null, error: null }
        }),
        single: vi.fn(async () => {
          if (table === 'stripe_charges') {
            return { data: { studio_id: 'studio-test-001', net_artist_cents: 9000, application_fee_cents: 1000, tip_amount_cents: 0, deposit_drawdown_cents: 0, transfer_id: null, tax_amount_cents: 500 }, error: null }
          }
          return { data: null, error: null }
        }),
        eq: vi.fn(() => ({
          order: vi.fn(() => ({
            limit: vi.fn(() => ({
              maybeSingle: vi.fn(async () => {
                if (table === 'commission_splits') return { data: { id: 'split-test-001' }, error: null }
                return { data: null, error: null }
              }),
            })),
          })),
          limit: vi.fn(() => ({
            maybeSingle: vi.fn(async () => {
              if (table === 'locations') return { data: { id: 'loc-test-001' }, error: null }
              return { data: null, error: null }
            }),
          })),
        })),
      })),
    })),
    update: vi.fn(() => ({ eq: vi.fn(async () => ({ error: null })) })),
  }))
  Object.assign(fromFn, { bind: vi.fn(() => fromFn) })

  const rpcFn = vi.fn(async (fn: string, args: Record<string, unknown>) => {
    rpcCalls.push({ fn, args })
    return { data: { id: 'mock-result' }, error: null }
  })
  const sb = {
    rpc: { bind: vi.fn(() => rpcFn) },
    from: fromFn,
  } as unknown as import('@/lib/payments/process-stripe-event').SupabaseServiceClient

  const breakdown: TaxBreakdownEntry[] = [
    { amount: 150, jurisdiction: { country: 'US' }, sourcing: 'destination', display_name: 'US Federal' },
    { amount: 100, jurisdiction: { country: 'US', state: 'NY' }, sourcing: 'destination', display_name: 'NY State' },
  ]
  const event = makePaymentIntentSucceededEvent({ taxAmount: 250, taxBreakdown: breakdown })
  await processStripeEvent(event, sb)

  const taxLineCalls = rpcCalls.filter(c => c.fn === RPC.COMMISSION_SPLIT_TAX_LINE_RECORD)
  expect(taxLineCalls).toHaveLength(2)
  const jurisdictions = taxLineCalls.map(c => c.args.p_jurisdiction)
  expect(jurisdictions).toContain('US')
  expect(jurisdictions).toContain('US-NY')
})

// Test 4: tax_breakdown present → TAX_REMITTANCE_ACCRUE called once per jurisdiction with correct quarter period
it('[Track A] PI succeeded with tax_breakdown → TAX_REMITTANCE_ACCRUE called once per jurisdiction with correct period (current quarter)', async () => {
  const rpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []

  const fromFn = vi.fn((table: string) => ({
    select: vi.fn(() => ({
      eq: vi.fn(() => ({
