          if (table === 'stripe_charges') {
            return { data: { studio_id: 'studio-test-001', net_artist_cents: 9000, application_fee_cents: 1000, tip_amount_cents: 0, deposit_drawdown_cents: 0, transfer_id: null, tax_amount_cents: 200 }, error: null }
          }
          return { data: null, error: null }
        }),
        eq: vi.fn(() => ({
          order: vi.fn(() => ({
            limit: vi.fn(() => ({
              maybeSingle: vi.fn(async () => {
                if (table === 'commission_splits') return { data: { id: 'split-test-001' }, error: null }
                return { data: null, error: null }
              }),
            })),
          })),
          limit: vi.fn(() => ({
            maybeSingle: vi.fn(async () => {
              if (table === 'locations') return { data: { id: 'loc-test-001' }, error: null }
              return { data: null, error: null }
            }),
          })),
        })),
      })),
    })),
    update: vi.fn(() => ({ eq: vi.fn(async () => ({ error: null })) })),
  }))
  Object.assign(fromFn, { bind: vi.fn(() => fromFn) })

  const rpcFn = vi.fn(async (fn: string, args: Record<string, unknown>) => {
    rpcCalls.push({ fn, args })
    return { data: { id: 'mock-result' }, error: null }
  })
  const sb = {
    rpc: { bind: vi.fn(() => rpcFn) },
    from: fromFn,
  } as unknown as import('@/lib/payments/process-stripe-event').SupabaseServiceClient

  const breakdown: TaxBreakdownEntry[] = [
    { amount: 200, jurisdiction: { country: 'US', state: 'NY' }, sourcing: 'destination', display_name: 'NY State' },
  ]
  const event = makePaymentIntentSucceededEvent({ taxAmount: 200, taxBreakdown: breakdown })
  await processStripeEvent(event, sb)

  const accruals = rpcCalls.filter(c => c.fn === RPC.TAX_REMITTANCE_ACCRUE)
  expect(accruals).toHaveLength(1)
  const period = accruals[0]?.args.p_period as string
  expect(period).toBeDefined()
  // Expect format YYYY-Qn
  expect(period).toMatch(/^\d{4}-Q[1-4]$/)
  // Verify the period matches the current quarter
  const now = new Date()
  const expectedQuarter = Math.floor(now.getMonth() / 3) + 1
  const expectedPeriod = `${now.getFullYear()}-Q${expectedQuarter}`
  expect(period).toBe(expectedPeriod)
})

// Test 5: Parent commission_split not found → logs warn, no COMMISSION_SPLIT_TAX_LINE_RECORD calls
it('[Track A] PI succeeded but parent commission_split not found → logs warn, no COMMISSION_SPLIT_TAX_LINE_RECORD calls', async () => {
  const { logger } = await import('@/lib/logger')
  const rpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []

