})

// Test 7: COMMISSION_SPLIT_TAX_LINE_RECORD failure → logs error but does not throw (recoverable)
it('[Track A] COMMISSION_SPLIT_TAX_LINE_RECORD failure → logs error but does not throw (recoverable via reconciliation)', async () => {
  const { logger } = await import('@/lib/logger')
  const rpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []

  const fromFn = vi.fn((table: string) => ({
    select: vi.fn(() => ({
      eq: vi.fn(() => ({
        maybeSingle: vi.fn(async () => {
          if (table === 'stripe_charges') return { data: { studio_id: 'studio-test-001' }, error: null }
          if (table === 'locations') return { data: { id: 'loc-test-001' }, error: null }
          return { data: null, error: null }
        }),
        single: vi.fn(async () => {
          if (table === 'stripe_charges') {
            return { data: { studio_id: 'studio-test-001', net_artist_cents: 9000, application_fee_cents: 1000, tip_amount_cents: 0, deposit_drawdown_cents: 0, transfer_id: null, tax_amount_cents: 200 }, error: null }
          }
