  Object.assign(fromFn, { bind: vi.fn(() => fromFn) })

  const rpcFn = vi.fn(async (fn: string, args: Record<string, unknown>) => {
    rpcCalls.push({ fn, args })
    if (fn === RPC.COMMISSION_SPLIT_TAX_LINE_RECORD) {
      return { data: null, error: { message: 'DB constraint violation' } }
    }
    return { data: { id: 'mock-result' }, error: null }
  })
  const sb = {
    rpc: { bind: vi.fn(() => rpcFn) },
    from: fromFn,
  } as unknown as import('@/lib/payments/process-stripe-event').SupabaseServiceClient

  const breakdown: TaxBreakdownEntry[] = [
    { amount: 200, jurisdiction: { country: 'US', state: 'NY' }, sourcing: 'destination', display_name: 'NY State' },
  ]
  const event = makePaymentIntentSucceededEvent({ taxAmount: 200, taxBreakdown: breakdown })

  // Must not throw even when the tax-line RPC errors
  await expect(processStripeEvent(event, sb)).resolves.toBeUndefined()

  expect(logger.error).toHaveBeenCalledWith(
    expect.objectContaining({ jurisdiction: 'US-NY' }),
    expect.stringContaining('commission_split_tax_line_record failed'),
  )
})

