59	function makeSupabaseMock(
60	  rpcHandler?: RpcHandler,
61	  chargeData?: Record<string, unknown> | null,
62	  splitData?: Record<string, unknown> | null,
63	  locationData?: Record<string, unknown> | null,
64	): SupabaseServiceClient {
65	  const defaultHandler: RpcHandler = async () => ({ data: { id: 'mock-result' }, error: null })
66	  const handler = rpcHandler ?? defaultHandler
67	
68	  const rpcFn = vi.fn(async (fn: string, args: Record<string, unknown>) => handler(fn, args))
69	
70	  // The production code uses TWO patterns for `from`:
71	  //
72	  //   1. Direct cast: `const fromUntyped = supabase.from as unknown as (table: string) => ...`
73	  //      Used in handlePaymentIntentStatusChange for stripe_charges reads.
