// Reusable terminal resolver so every chain shape returns the right data for the table.
const resolveMaybySingle = async (t: string) => {
  if (t === 'stripe_charges') return { data: { studio_id: 'studio-test-001' }, error: null }
  if (t === 'commission_splits') return { data: splitData ?? { id: 'split-test-001' }, error: null }
  if (t === 'locations' || t === 'studio_locations') {
    return { data: locationData !== undefined ? locationData : { id: 'loc-test-001' }, error: null }
  }
  return { data: { studio_id: 'studio-test-001' }, error: null }
}

// Deep chain builder that satisfies ALL query shapes used by the S17 production code:
//   • .select().eq().maybeSingle()                        — stripe_charges lookup
//   • .select().eq().single()                             — stripe_charges read
//   • .select().eq().eq().order().limit().maybeSingle()   — commission_splits lookup
//   • .select().eq().limit().maybeSingle()                — locations lookup
const makeEqChain = (t: string): Record<string, unknown> => ({
  maybeSingle: vi.fn(async () => resolveMaybySingle(t)),
  single: vi.fn(async () => {
    if (t === 'stripe_charges') return { data: defaultChargeData, error: null }
    return { data: null, error: null }
  }),
  // Second .eq() → supports commission_splits chaining
  eq: vi.fn(() => ({
    order: vi.fn(() => ({
      limit: vi.fn(() => ({
        maybeSingle: vi.fn(async () => resolveMaybySingle(t)),
      })),
    })),
    limit: vi.fn(() => ({
      maybeSingle: vi.fn(async () => resolveMaybySingle(t)),
    })),
    maybeSingle: vi.fn(async () => resolveMaybySingle(t)),
  })),
  // .limit() directly after first .eq() → supports locations chaining
  limit: vi.fn(() => ({
    maybeSingle: vi.fn(async () => resolveMaybySingle(t)),
  })),
  order: vi.fn(() => ({
    limit: vi.fn(() => ({
      maybeSingle: vi.fn(async () => resolveMaybySingle(t)),
    })),
  })),
})

const fromFn = vi.fn((table: string) => ({
  select: vi.fn(() => ({
    eq: vi.fn(() => makeEqChain(table)),
  })),
  update: vi.fn(() => ({
    eq: vi.fn(async () => ({ error: null })),
  })),
}))

